import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'src'))

from docich.hanjuku_speedrun.hanjuku.flows import shop
from docich.hanjuku_speedrun.hanjuku.os_layer.commands import pad
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import Screen

QUOTE = '2こで100Gになりまんな よろしいでっか? うむッ! いかんッ!'


def screen(text=QUOTE):
    return Screen([], (200, 190, 214, 203), text, kind='shop_quantity')


def memory():
    return {'shop': {'items': [['カード', 3, 50]], 'want': None},
            'tick': 1, '_records': []}


def test_one_read_keeps_the_harmless_b(monkeypatch):
    monkeypatch.setattr(shop, 'menu_to', lambda *_: 'right')
    mem = memory()
    assert shop.quantity_step(screen(), mem) == [pad('b')]
    assert mem['shop']['quote_stall']['n'] == 1


def test_the_stalled_quote_is_declined_with_ikann(monkeypatch):
    monkeypatch.setattr(shop, 'menu_to', lambda *_: 'right')
    mem = memory()
    for _ in range(shop.QUOTE_STALL_LIMIT - 1):
        assert shop.quantity_step(screen(), mem) == [pad('b')]
    assert shop.quantity_step(screen(), mem) == ['right']
    assert any(r['decision'] == 'buy_skip' for r in mem['_records'])
    assert 'quote_stall' not in mem['shop']


def test_an_unread_choice_falls_back_to_b(monkeypatch):
    monkeypatch.setattr(shop, 'menu_to', lambda *_: None)
    mem = memory()
    for _ in range(shop.QUOTE_STALL_LIMIT - 1):
        shop.quantity_step(screen(), mem)
    assert shop.quantity_step(screen(), mem) == [pad('b')]


def test_a_different_quote_resets_the_watch(monkeypatch):
    monkeypatch.setattr(shop, 'menu_to', lambda *_: 'right')
    mem = memory()
    for _ in range(shop.QUOTE_STALL_LIMIT - 1):
        shop.quantity_step(screen(), mem)
    assert shop.quantity_step(screen(text=QUOTE.replace('2こで', '5こで')),
                              mem) == [pad('b')]
